def overlap_minutes(meetings: list[list[int]], k: int) -> int:
    if len(meetings) < k:
        return 0

    events: dict[int, int] = {}
    for start, end in meetings:
        if start < end:
            events[start] = events.get(start, 0) + 1
            events[end] = events.get(end, 0) - 1

    total = 0
    active = 0
    prev_t: int | None = None

    for t, delta in sorted(events.items()):
        if prev_t is not None and active >= k:
            total += t - prev_t
        active += delta
        prev_t = t

    return total
